import{_ as t,o,c as r,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/11-数字时代的防御行为.md","filePath":"books/attached/11-数字时代的防御行为.md","lastUpdated":1794316978000}'),n={name:"books/attached/11-数字时代的防御行为.md"};function l(d,a,_,c,p,i){return o(),r("div",null,[...a[0]||(a[0]=[e("h3",{id:"数字时代的防御行为",tabindex:"-1"},[s("数字时代的防御行为 "),e("a",{class:"header-anchor",href:"#数字时代的防御行为","aria-label":'Permalink to "数字时代的防御行为"'},"​")],-1),e("p",null,"在对日常生活中依恋风格的含义有了全新的理解之后，我们会对人们的行为方式有着不一样的认知。我们曾经常常用行为来定义人们的人格特点。那些被标志成神经过敏的人，现在通过依恋理论来看，或许就会得到更加清晰准确的刻画。我们的研究，为塔玛拉在与那个令她痛苦的男友格雷格分手过程中所遭遇的艰难，赋予了一种全新的视角。或许这种艰难并不源于塔玛拉的懦弱，而是来自于一种天生的本能，这种本能令人倾其所有去维持与依恋对象的关系，而这种本能很大程度上来源于焦虑型依恋风格。",-1),e("p",null,"对塔玛拉来说，那种一心想与格雷格在一起的需要，来源于对危险的极度敏锐。这种危机感包括爱人的失控，爱人的不理会，或是别的什么麻烦。而从进化的角度来说，在这种情形下，与恋人决断是一种非常不理智的做法。而这时候用一些防御行为，则看上去是非常有用的，比如说夺命连环电话，或者试着让对方吃醋云云。",-1),e("p",null,"依恋理论真正令我们着迷的地方在于，它在整个人类群体中都是适用的，是以全人类作为对象而提炼出来。而不像很多其他的心理学范式，或许只是基于某些接受治疗的伴侣而提出。这种学说为所有的群体提供帮助，包括那些幸福融洽的伴侣，那些饱经不幸的恋人，那些从不接受治疗又或是积极配合治疗的伴侣们。这种理论让我们知道，在亲密关系中哪儿出了问题，同时也让我们发现值得肯定的地方，它同样让我们全面地了解了各个人群，并且从中挑选到最佳伴侣。而这一切在绝大多数有关亲密关系的读物中，是很少提及的。另外，这个理论也没有直接把行为定义成健康或不健康的。没有一种依恋风格本身就是“病理性的”。相反，那些在从前看来很奇怪，或者说很难理解的恋爱行为，现在却变得可以理解，可以预测，甚至理所当然了。你跟一个人交往，他却不能承诺自己爱你？可以理解。你说你想分手，然后几分钟后就变卦了，并且决定对现在的感情矢志不渝？也情有可原。",-1),e("p",null,"那这些行为到底有没有意义，或者说值不值得去做呢？这又得另说了。安全型依恋风格的人，即使不动用防御手段，依然知道如何表达自己的期望，以及如何有效地回应对方的诉求。而对于剩下的人群，就得从理解开始做起。",-1)])])}const h=t(n,[["render",l]]);export{f as __pageData,h as default};
